#include <stdio.h>

void swap(int *left, int *right)
{
    int temp = *left;
    *left = *right;
    *right = temp;
}

int main(void)
{
    int a = 40, b = 90;
    swap(&a, &b);
    printf("%d %d\n", a, b);
    return 0;
}

#include <stdio.h>

int *find(int *a, size_t n, int key)
{
    for (size_t i = 0; i < n; i++) {
        if (a[i] == key) {
            return a + i;
        }
    }
    return NULL;
}

int main(void)
{
    int values[] = {3, 8, 5};
    int *found = find(values, 3, 8);
    if (found != NULL) {
        *found = 10;
    }
    printf("%d\n", values[1]);
    return 0;
}

#include <stdio.h>

int *counter(void)
{
    static int count = 0;
    count++;
    return &count;
}

int main(void)
{
    int *first = counter();
    int before = *first;
    counter();
    printf("%d %d\n", before, *first);
    return 0;
}

